def strategy(history, rng):
    n = len(history)
    if n < 3:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    opp_prev = history[-2][1]

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_streak += 1
        else:
            break

    cd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'D':
            cd_streak += 1
        else:
            break

    opp_c_10 = 0
    for i in range(max(0, n - 10), n):
        if history[i][1] == 'C':
            opp_c_10 += 1

    failed_count = 0
    start = n - opp_d_streak
    for i in range(max(1, start), n):
        if history[i] == ('C', 'D') and history[i - 1] == ('D', 'D'):
            failed_count += 1

    if opp_last == 'D':
        if my_last == 'C':
            if cd_streak == 1 and history[-2] == ('D', 'D') and failed_count == 1:
                return 'C'
            if opp_prev == 'C' and opp_d_streak <= 1 and failed_count == 0:
                return 'C'
            return 'D'

        if opp_c_10 == 0:
            return 'D'
        if failed_count > 0:
            return 'D'
        if opp_d_streak > 10:
            return 'D'
        if dd_streak >= 1:
            return 'C'
        return 'D'

    return 'C'
